<?php
if ( ! defined( 'ABSPATH' ) ) exit;
$client = OFP_Auth::current_client();
$can_rent = $client && OFP_Property_Rent::can_manage( (int) $client->id );
global $wpdb; $p = $wpdb->prefix; $notice = ''; $error = ''; $offer_link = '';

if ( $can_rent && $_SERVER['REQUEST_METHOD'] === 'POST' ) {
    $action = sanitize_key( $_POST['ofp_rent_action'] ?? '' );
    if ( ! wp_verify_nonce( $_POST['ofp_rent_nonce'] ?? '', 'ofp_rent_' . $action ) ) $error = 'Security check failed. Please try again.';
    elseif ( $action === 'save_option' ) {
        $result = OFP_Property_Rent::save_rent_option( (int) $client->id, absint( $_POST['property_id'] ?? 0 ), [ 'period' => wp_unslash( $_POST['period'] ?? '' ), 'custom_days' => $_POST['custom_days'] ?? 0, 'amount' => $_POST['amount'] ?? 0, 'is_active' => 1 ] );
        $error = is_wp_error( $result ) ? $result->get_error_message() : ''; $notice = $error ? '' : 'Rent option saved.';
    } elseif ( $action === 'create_offer' ) {
        $tenant = OFP_Property_Rent::find_or_create_tenant( (int) $client->id, [ 'full_name' => wp_unslash( $_POST['tenant_name'] ?? '' ), 'phone' => wp_unslash( $_POST['tenant_phone'] ?? '' ), 'email' => wp_unslash( $_POST['tenant_email'] ?? '' ) ] );
        $offer = is_wp_error( $tenant ) ? $tenant : OFP_Property_Rent::create_lease_offer( (int) $client->id, absint( $_POST['property_id'] ?? 0 ), (int) $tenant['tenant_id'], absint( $_POST['rent_option_id'] ?? 0 ), [ 'terms_text' => wp_unslash( $_POST['terms_text'] ?? '' ) ] );
        if ( is_wp_error( $offer ) ) $error = $offer->get_error_message(); else { $offer_link = home_url( '/tenant-lease/' . rawurlencode( $offer['offer_token'] ) . '/' ); $notice = 'Lease offer created. Share the secure link below if needed.'; }
    } elseif ( $action === 'cash_payment' ) {
        $result = OFP_Property_Lease_Payment::record_cash_payment( (int) $client->id, absint( $_POST['lease_id'] ?? 0 ), (float) ( $_POST['amount'] ?? 0 ), sanitize_text_field( wp_unslash( $_POST['reference'] ?? '' ) ) );
        $error = is_wp_error( $result ) ? $result->get_error_message() : ''; $notice = $error ? '' : 'Cash payment recorded.';
    }
}
$properties = $client ? $wpdb->get_results( $wpdb->prepare( "SELECT id,title FROM {$p}ofp_properties WHERE client_id=%d AND listing_type IN ('rent','shortlet') ORDER BY title", $client->id ) ) : [];
$options = $client ? $wpdb->get_results( $wpdb->prepare( "SELECT ro.*,pr.title property_title FROM {$p}ofp_property_rent_options ro JOIN {$p}ofp_properties pr ON pr.id=ro.property_id WHERE ro.client_id=%d AND ro.is_active=1 ORDER BY pr.title,ro.amount", $client->id ) ) : [];
$leases = $client ? $wpdb->get_results( $wpdb->prepare( "SELECT l.*,t.full_name,t.phone,pr.title property_title FROM {$p}ofp_property_leases l JOIN {$p}ofp_property_tenants t ON t.id=l.tenant_id LEFT JOIN {$p}ofp_properties pr ON pr.id=l.property_id WHERE l.client_id=%d ORDER BY l.created_at DESC LIMIT 100", $client->id ) ) : [];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Tenants — OFast Pipeline</title><?php wp_head(); ?><link rel="stylesheet" href="<?php echo esc_url(OFP_URL.'assets/css/client-portal.css?v='.OFP_VERSION); ?>"></head><body class="ofp-portal-body"><?php include OFP_PATH.'public/templates/partials/nav.php'; ?><div class="ofp-container"><div style="padding-bottom:60px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px"><div><h1 style="margin:0;color:var(--text-main)">Tenants &amp; leases</h1><p style="color:var(--text-muted);margin:8px 0 0">Create rent options, send lease offers, and record rent payments.</p></div></div><?php if(!$can_rent): ?><div class="ofp-card"><h2>Gold feature</h2><p>Rent management is available on the Gold plan.</p><a class="ofp-btn ofp-btn-primary" href="<?php echo esc_url(home_url('/pricing')); ?>">View plans</a></div><?php else: ?><?php if($notice): ?><div class="notice notice-success"><p><?php echo esc_html($notice); ?></p></div><?php endif; ?><?php if($error): ?><div class="notice notice-error"><p><?php echo esc_html($error); ?></p></div><?php endif; ?><?php if($offer_link): ?><div class="ofp-card" style="margin-bottom:18px"><strong>Secure tenant link</strong><br><a href="<?php echo esc_url($offer_link); ?>" target="_blank"><?php echo esc_html($offer_link); ?></a></div><?php endif; ?><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px"><div class="ofp-card"><h2>Add rent option</h2><form method="post"><?php wp_nonce_field('ofp_rent_save_option','ofp_rent_nonce'); ?><input type="hidden" name="ofp_rent_action" value="save_option"><p><select class="ofp-select" name="property_id" required><option value="">Rental property</option><?php foreach($properties as $x): ?><option value="<?php echo esc_attr($x->id); ?>"><?php echo esc_html($x->title); ?></option><?php endforeach; ?></select></p><p><select class="ofp-select" name="period"><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="biannual">Biannual</option><option value="yearly">Yearly</option><option value="shortlet">Shortlet</option><option value="custom">Custom days</option></select></p><p><input class="ofp-input" type="number" name="custom_days" min="1" placeholder="Custom days only"></p><p><input class="ofp-input" type="number" name="amount" min="0.01" step="0.01" placeholder="Amount (NGN)" required></p><button class="ofp-btn ofp-btn-primary">Save option</button></form></div><div class="ofp-card"><h2>New lease offer</h2><form method="post"><?php wp_nonce_field('ofp_rent_create_offer','ofp_rent_nonce'); ?><input type="hidden" name="ofp_rent_action" value="create_offer"><p><select class="ofp-select" name="property_id" required><?php foreach($properties as $x): ?><option value="<?php echo esc_attr($x->id); ?>"><?php echo esc_html($x->title); ?></option><?php endforeach; ?></select></p><p><select class="ofp-select" name="rent_option_id" required><?php foreach($options as $x): ?><option value="<?php echo esc_attr($x->id); ?>"><?php echo esc_html($x->property_title.' — '.OFP_Property_Rent::period_label($x->period,(int)$x->custom_days).' — NGN '.number_format($x->amount,2)); ?></option><?php endforeach; ?></select></p><p><input class="ofp-input" name="tenant_name" placeholder="Tenant name" required></p><p><input class="ofp-input" name="tenant_phone" placeholder="Tenant phone" required></p><p><input class="ofp-input" type="email" name="tenant_email" placeholder="Tenant email"></p><p><textarea class="ofp-textarea" name="terms_text" rows="3" placeholder="Lease terms"></textarea></p><button class="ofp-btn ofp-btn-primary">Create offer</button></form></div></div><div class="ofp-card" style="margin-top:20px"><h2>Lease history</h2><div class="ofp-table-responsive"><table class="ofp-table"><thead><tr><th>Tenant</th><th>Property</th><th>Period</th><th>Balance</th><th>Status</th><th>Cash payment</th></tr></thead><tbody><?php if(!$leases): ?><tr><td colspan="6">No lease offers yet.</td></tr><?php else: foreach($leases as $x): ?><tr><td><strong><?php echo esc_html($x->full_name); ?></strong><br><small><?php echo esc_html($x->phone); ?></small></td><td><?php echo esc_html($x->property_title); ?></td><td><?php echo esc_html(OFP_Property_Rent::period_label($x->rent_period,(int)$x->custom_days)); ?></td><td>NGN <?php echo esc_html(number_format($x->balance,2)); ?></td><td><?php echo esc_html(ucwords(str_replace('_',' ',$x->status))); ?></td><td><?php if($x->accepted_at&&(float)$x->balance>0): ?><form method="post" style="display:flex;gap:6px"><?php wp_nonce_field('ofp_rent_cash_payment','ofp_rent_nonce'); ?><input type="hidden" name="ofp_rent_action" value="cash_payment"><input type="hidden" name="lease_id" value="<?php echo esc_attr($x->id); ?>"><input class="ofp-input" style="width:100px" name="amount" type="number" min="0.01" max="<?php echo esc_attr($x->balance); ?>" step="0.01" placeholder="Amount" required><button class="ofp-btn ofp-btn-sm">Record</button></form><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?php endif; ?></div></div><?php wp_footer(); ?></body></html>
